import {Config} from 'alinea'
import {createCMS} from 'alinea/server'

export const Page = Config.document('Page', {
  fields: {}
})

export const cms = createCMS({
  schema: {Page},
  workspaces: {
    main: Config.workspace('Example', {
      source: 'content',
      mediaDir: 'public/media',
      roots: {
        pages: Config.root('Pages', {contains: ['Page']}),
        media: Config.media()
      }
    })
  },
  baseUrl: {
    development: 'http://localhost:3000',
    production: 'https://example.com'
  },
  handlerUrl: '/api/cms',
  adminPath: '/admin',
  preview: true
})

import {serve} from '@hono/node-server'
import {createMiddleware} from 'alinea/server'
import {Hono} from 'hono'
import {cms, Page} from './cms.ts'

const alinea = createMiddleware(cms)
const app = new Hono()

app.get('*', async c => {
  const page = await cms.first({type: Page, url: c.req.path})
  if (!page) return c.notFound()
  return c.html(`<!DOCTYPE html>
    <html>
      <body><h1>${page.title}</h1></body>
    </html>`)
})

serve({
  port: 3000,
  fetch: request => alinea(request, () => app.fetch(request))
})

